1	// SPDX-License-Identifier: BSD-3-Clause
2	// Copyright (c) 2025-2026 Kevin Barnard and minix.rs Contributors
3	// `Prot::RO_DATA` and `AddrSpace::{walk_pt, destroy}` are part of the API
4	// surface that later Phase 3 slices consume (region tracking, exec/exit
5	// teardown); 3.1a's smoke test and 3.3's `VMCTL_PT_MAP`/`PT_UNMAP` exercise
6	// `Prot::RW_DATA`, `map_page_in`, and `unmap_page_in`. Surfacing the rest now
7	// keeps the API stable across slices.
8	#![allow(dead_code)]
9	
10	//! Per-process aarch64 address space.
11	//!
12	//! Slice 3.1a introduces this API but no proc consumes it yet — the kmain
13	//! smoke test exercises it standalone, and slice 3.1b will swap `userland.rs`
14	//! over so each EL0 stub gets its own [`AddrSpace`] instead of the shared
15	//! static L0/L1/L2/L3 arrays.
16	//!
17	//! The walk follows the same 4 KiB-granule, 4-level, 48-bit-VA layout that
18	//! [`super::mmu`] already documents and verifies on Limine handoff. Intermediate
19	//! tables (L1, L2, L3) are allocated on demand from the frame allocator —
20	//! [`AddrSpace::new`] only allocates the L0 root; each `map_page` walk
21	//! allocates whatever sub-tables are missing.
22	//!
23	//! All page-table writes go through HHDM — we never touch a table via its
24	//! own VA, because at slice-3.1a time the address space isn't activated.
25	//! Slice 3.1b's context switch will install [`AddrSpace::ttbr0_pa`] into
26	//! TTBR0_EL1; until then, AddrSpaces are passive data structures.
27	
28	use crate::arch::aarch64::mmu::{
29	    ATTR_IDX_NORMAL, PAGE_SHIFT, PAGE_SIZE, PTE_AF, PTE_AP_RO_EL0, PTE_AP_RW_EL0, PTE_PXN,
30	    PTE_SH_INNER, PTE_TABLE, PTE_UXN, PTE_VALID, PTES_PER_LEVEL, pte_attr_idx,
31	};
32	use crate::mm::{FRAME_SIZE, Frame, alloc_frame, free_frame, phys_to_hhdm};
33	use minixrs_kernel_shared::message::USER_VA_TOP;
34	
35	// `check_va` aligns on `FRAME_SIZE` while `pte_index` shifts by `PAGE_SHIFT`,
36	// so an allocator frame and an L3 leaf must describe the same granule. The two
37	// constants are declared independently (`mm::frame` and `mmu`), so pin them.
38	const _: () = assert!(FRAME_SIZE == PAGE_SIZE);
39	const _: () = assert!(1usize << PAGE_SHIFT == PAGE_SIZE);
40	
41	/// User-page permission. Maps onto the aarch64 stage-1 descriptor's AP +
42	/// PXN + UXN bits; kernel callers describe intent here and `prot_attrs()`
43	/// converts to the bit pattern.
44	#[derive(Copy, Clone, Debug)]
45	pub struct Prot {
46	    /// EL0 may write.
47	    pub writable: bool,
48	    /// EL0 may fetch from this page (code).
49	    pub executable: bool,
50	}
51	
52	impl Prot {
53	    pub const RO_CODE: Self = Self {
54	        writable: false,
55	        executable: true,
56	    };
57	    pub const RW_DATA: Self = Self {
58	        writable: true,
59	        executable: false,
60	    };
61	    pub const RO_DATA: Self = Self {
62	        writable: false,
63	        executable: false,
64	    };
65	}
66	
67	fn prot_attrs(prot: Prot) -> u64 {
68	    let ap = if prot.writable {
69	        PTE_AP_RW_EL0
70	    } else {
71	        PTE_AP_RO_EL0
72	    };
73	    let uxn = if prot.executable { 0 } else { PTE_UXN };
74	    PTE_AF | PTE_SH_INNER | ap | PTE_PXN | uxn | pte_attr_idx(ATTR_IDX_NORMAL)
75	}
76	
77	/// Errors from [`AddrSpace`] operations.
78	#[derive(Copy, Clone, Debug, PartialEq, Eq)]
79	pub enum MapError {
80	    /// Frame allocator returned `None`; no physical memory left for an
81	    /// intermediate page table or for the L0 root.
82	    OutOfMemory,
83	    /// `va` is not 4 KiB-aligned.
84	    Misaligned,
85	    /// `va` is outside the 48-bit user-VA window.
86	    OutOfRange,
87	    /// A leaf PTE is already present at `va` and the caller asked for a
88	    /// fresh mapping. Use [`AddrSpace::unmap_page`] to clear first.
89	    AlreadyMapped,
90	}
91	
92	/// One per-process page-table tree, rooted at the L0 frame whose PA goes
93	/// into TTBR0_EL1 on context switch.
94	pub struct AddrSpace {
95	    /// PA of the L0 page-table root. Always frame-aligned.
96	    pub ttbr0_pa: u64,
97	}
98	
99	impl AddrSpace {
100	    /// Build a fresh, empty address space. Allocates one frame for the L0
101	    /// root; intermediate L1/L2/L3 tables come later, on first `map_page`.
102	    pub fn new() -> Result<Self, MapError> {
103	        let l0 = alloc_frame().ok_or(MapError::OutOfMemory)?;
104	        // `alloc_frame` zeroes the frame, so the L0 starts all-invalid.
105	        Ok(Self {
106	            ttbr0_pa: l0.addr(),
107	        })
108	    }
109	
110	    /// Install a single 4 KiB mapping `va → pa` with the given permissions.
111	    ///
112	    /// Intermediate L1/L2/L3 tables are allocated from the frame allocator
113	    /// as needed. Returns `Err(AlreadyMapped)` if `va` already has a leaf
114	    /// PTE (callers must `unmap_page` first to replace).
115	    pub fn map_page(&mut self, va: u64, pa: u64, prot: Prot) -> Result<(), MapError> {
116	        map_page_in(self.ttbr0_pa, va, pa, prot)
117	    }
118	
119	    /// Clear the leaf PTE at `va`. Returns `Some(pa)` if a mapping was
120	    /// present, `None` otherwise. The freed PA is returned to the caller —
121	    /// it's the caller's job to `free_frame` if appropriate (the page
122	    /// might be a CoW share, a device PA, or stale; the address space
123	    /// itself doesn't know).
124	    ///
125	    /// Does not free intermediate L1/L2/L3 tables even if they become
126	    /// empty — that's left to [`Self::destroy`]. Avoiding incremental
127	    /// pruning keeps `unmap_page` O(walk) and matches what real MINIX 3
128	    /// does (lazy pruning at exec/exit time).
129	    pub fn unmap_page(&mut self, va: u64) -> Option<u64> {
130	        unmap_page_in(self.ttbr0_pa, va)
131	    }
132	
133	    /// Walk the page table to find the PA backing `va`, or `None` if `va`
134	    /// is unmapped.
135	    pub fn walk_pt(&self, va: u64) -> Option<u64> {
136	        walk_pt_in(self.ttbr0_pa, va).map(|(pa, _)| pa)
137	    }
138	
139	    /// Free every intermediate L1/L2/L3 table and the L0 root.
140	    ///
141	    /// Leaf-page frames (the PAs that `map_page` installed) are *not*
142	    /// freed — the address space owns the page-table tree, not the pages
143	    /// it points at. The caller is responsible for tracking and freeing
144	    /// leaf frames before calling this; otherwise they leak. Phase 3.5's
145	    /// VM region tracker is what eventually owns leaf-frame lifetimes.
146	    pub fn destroy(self) {
147	        // Walk the L0 root, recursing into table descriptors. Page
148	        // descriptors (PTE_VALID & PTE_TABLE both set at L3) are leaves
149	        // and left alone; intermediate tables (PTE_VALID & PTE_TABLE at
150	        // L0/L1/L2) get recursed-into then freed.
151	        free_subtree(self.ttbr0_pa, 0);
152	        free_frame(Frame::from_addr(self.ttbr0_pa));
153	    }
154	}
155	
156	// ----- helpers --------------------------------------------------------------
157	
158	/// Install a single 4 KiB mapping `va → pa` into the page-table tree rooted
159	/// at `ttbr0_pa`, allocating intermediate L1/L2/L3 tables on demand.
160	///
161	/// This is the body of [`AddrSpace::map_page`], exposed as a free function
162	/// so the kernel can map into a proc's *live* address space given only the
163	/// `ttbr0_pa` stored on its [`Proc`](crate::proc::Proc) slot — without
164	/// reconstructing an owning [`AddrSpace`] value (whose future `destroy`
165	/// semantics would risk freeing a tree it does not own). The slice-3.2
166	/// page-fault handler and slice-3.3's `VMCTL_PT_MAP` both go through here.
167	///
168	/// All table access is via HHDM; the target AS need not be the active one.
169	pub fn map_page_in(ttbr0_pa: u64, va: u64, pa: u64, prot: Prot) -> Result<(), MapError> {
170	    check_va(va)?;
171	    if pa & (FRAME_SIZE as u64 - 1) != 0 {
172	        return Err(MapError::Misaligned);
173	    }
174	
175	    let l1 = ensure_next_table(ttbr0_pa, pte_index(va, 0))?;
176	    let l2 = ensure_next_table(l1, pte_index(va, 1))?;
177	    let l3 = ensure_next_table(l2, pte_index(va, 2))?;
178	    let l3_table = table_mut(l3);
179	    let idx = pte_index(va, 3);
180	    if l3_table[idx] & PTE_VALID != 0 {
181	        return Err(MapError::AlreadyMapped);
182	    }
183	    l3_table[idx] = make_page_desc(pa, prot_attrs(prot));
184	    Ok(())
185	}
186	
187	/// Clear the leaf PTE at `va` in the page-table tree rooted at `ttbr0_pa`,
188	/// returning `Some(pa)` of the page that was mapped or `None` if `va` had no
189	/// leaf PTE.
190	///
191	/// This is the body of [`AddrSpace::unmap_page`], exposed as a free function
192	/// for the same reason as [`map_page_in`]: slice-3.3's `VMCTL_PT_UNMAP` clears
193	/// a PTE in a proc's *live* tree given only the `ttbr0_pa` from its
194	/// [`Proc`](crate::proc::Proc) slot. Intermediate L1/L2/L3 tables are left in
195	/// place (lazy pruning happens at [`AddrSpace::destroy`]); the freed PA is the
196	/// caller's to `free_frame` if appropriate.
197	pub fn unmap_page_in(ttbr0_pa: u64, va: u64) -> Option<u64> {
198	    check_va(va).ok()?;
199	    let l1 = next_table(ttbr0_pa, pte_index(va, 0))?;
200	    let l2 = next_table(l1, pte_index(va, 1))?;
201	    let l3 = next_table(l2, pte_index(va, 2))?;
202	    let l3_table = table_mut(l3);
203	    let idx = pte_index(va, 3);
204	    let pte = l3_table[idx];
205	    if pte & PTE_VALID == 0 {
206	        return None;
207	    }
208	    l3_table[idx] = 0;
209	    Some(pte & PA_MASK)
210	}
211	
212	/// Translate the page-aligned `va` in the tree rooted at `ttbr0_pa` to its
213	/// backing frame PA and the EL0 permissions its leaf descriptor carries.
214	/// Returns `None` for a walk miss, a misaligned or out-of-range `va`, or a
215	/// `ttbr0_pa` that names no tree.
216	///
217	/// This is the body of [`AddrSpace::walk_pt`], exposed as a free function for
218	/// the same reason as [`map_page_in`] / [`unmap_page_in`]: the kernel resolves
219	/// a user VA in a proc's *live* address space given only the `ttbr0_pa` stored
220	/// on its [`Proc`](crate::proc::Proc) slot. Slice 5.1's fault-safe user copy
221	/// (`mm::uaccess`) is the first consumer; slice 5.2's grant engine is the next.
222	/// The [`Prot`] half is what lets a write reject a read-only destination — the
223	/// kernel copies through the HHDM alias, which the MMU's EL0 permission bits do
224	/// not police.
225	///
226	/// All table access is via HHDM; the target AS need not be the active one.
227	pub fn walk_pt_in(ttbr0_pa: u64, va: u64) -> Option<(u64, Prot)> {
228	    // A kernel task has no user AS (`ttbr0_pa == 0`). The old copy helpers
229	    // walked the live TTBR0 and could not hit this; a `ttbr0_pa`-taking walk
230	    // can, and `table_ref(0)` would read whatever the HHDM maps at PA 0.
231	    if ttbr0_pa == 0 || ttbr0_pa & (FRAME_SIZE as u64 - 1) != 0 {
232	        return None;
233	    }
234	    check_va(va).ok()?;
235	    let l1 = next_table(ttbr0_pa, pte_index(va, 0))?;
236	    let l2 = next_table(l1, pte_index(va, 1))?;
237	    let l3 = next_table(l2, pte_index(va, 2))?;
238	    let pte = table_ref(l3)[pte_index(va, 3)];
239	    if pte & PTE_VALID == 0 {
240	        None
241	    } else {
242	        Some((pte & PA_MASK, pte_prot(pte)))
243	    }
244	}
245	
246	/// Visit every valid L3 leaf mapping in the tree rooted at `ttbr0_pa`,
247	/// calling `f(va, pa, prot)` for each in ascending-VA order.
248	///
249	/// This is the enumeration primitive slice 4.6 needs twice: `SYS_FORK` copies
250	/// every parent page into a fresh child tree, and `SYS_EXIT` frees every leaf
251	/// frame before [`AddrSpace::destroy`] (which only frees the tables). `f` may
252	/// allocate frames and write *other* trees, but must not modify this one —
253	/// each table is snapshotted before its entries are walked (the
254	/// [`free_subtree`] pattern), so mid-walk edits to `ttbr0_pa`'s tree would be
255	/// silently ignored, not honored. Returning `Err` aborts the walk (fork's
256	/// out-of-memory unwind).
257	pub fn walk_leaves(
258	    ttbr0_pa: u64,
259	    f: &mut dyn FnMut(u64, u64, Prot) -> Result<(), MapError>,
260	) -> Result<(), MapError> {
261	    let l0: [u64; PTES_PER_LEVEL] = *table_ref(ttbr0_pa);
262	    for (i0, d0) in l0.iter().enumerate() {
263	        if !is_table_desc(*d0) {
264	            continue;
265	        }
266	        let l1: [u64; PTES_PER_LEVEL] = *table_ref(d0 & PA_MASK);
267	        for (i1, d1) in l1.iter().enumerate() {
268	            if !is_table_desc(*d1) {
269	                continue;
270	            }
271	            let l2: [u64; PTES_PER_LEVEL] = *table_ref(d1 & PA_MASK);
272	            for (i2, d2) in l2.iter().enumerate() {
273	                if !is_table_desc(*d2) {
274	                    continue;
275	                }
276	                let l3: [u64; PTES_PER_LEVEL] = *table_ref(d2 & PA_MASK);
277	                for (i3, d3) in l3.iter().enumerate() {
278	                    if *d3 & PTE_VALID == 0 {
279	                        continue;
280	                    }
281	                    let va = ((i0 as u64) << 39)
282	                        | ((i1 as u64) << 30)
283	                        | ((i2 as u64) << 21)
284	                        | ((i3 as u64) << PAGE_SHIFT);
285	                    f(va, *d3 & PA_MASK, pte_prot(*d3))?;
286	                }
287	            }
288	        }
289	    }
290	    Ok(())
291	}
292	
293	/// The AP bit that distinguishes read-only from read-write at EL0: set in
294	/// `PTE_AP_RO_EL0` (0b11 << 6), clear in `PTE_AP_RW_EL0` (0b01 << 6).
295	const PTE_AP_READONLY_BIT: u64 = PTE_AP_RO_EL0 & !PTE_AP_RW_EL0;
296	
297	/// Recover the mapping intent from a leaf page descriptor — the inverse of
298	/// [`prot_attrs`]. Writable ⇔ the AP read-only bit is clear; executable ⇔
299	/// UXN is clear. Fork uses this to re-install a copied page with the same
300	/// permissions the parent had.
301	fn pte_prot(pte: u64) -> Prot {
302	    Prot {
303	        writable: pte & PTE_AP_READONLY_BIT == 0,
304	        executable: pte & PTE_UXN == 0,
305	    }
306	}
307	
308	/// True when `desc` is a valid table descriptor (at L0–L2 — the only kind of
309	/// valid entry [`ensure_next_table`] writes at those levels; a valid entry
310	/// with `PTE_TABLE` clear would be a block descriptor, which this kernel
311	/// never maps).
312	fn is_table_desc(desc: u64) -> bool {
313	    desc & (PTE_VALID | PTE_TABLE) == (PTE_VALID | PTE_TABLE)
314	}
315	
316	/// Mask selecting the PA bits of a descriptor (47:12).
317	const PA_MASK: u64 = 0x0000_FFFF_FFFF_F000;
318	
319	fn check_va(va: u64) -> Result<(), MapError> {
320	    if va & (FRAME_SIZE as u64 - 1) != 0 {
321	        return Err(MapError::Misaligned);
322	    }
323	    if va >= USER_VA_TOP {
324	        return Err(MapError::OutOfRange);
325	    }
326	    Ok(())
327	}
328	
329	fn pte_index(va: u64, level: u32) -> usize {
330	    let shift = PAGE_SHIFT + 9 * (3 - level);
331	    ((va >> shift) & 0x1FF) as usize
332	}
333	
334	const fn make_table_desc(next_table_pa: u64) -> u64 {
335	    (next_table_pa & PA_MASK) | PTE_VALID | PTE_TABLE
336	}
337	
338	const fn make_page_desc(pa: u64, attrs: u64) -> u64 {
339	    // At L3, both PTE_VALID and PTE_TABLE bits must be set to distinguish a
340	    // page descriptor from an invalid entry. `mmu::make_page_desc` documents
341	    // this; we mirror the same encoding.
342	    (pa & PA_MASK) | PTE_VALID | PTE_TABLE | attrs
343	}
344	
345	/// Borrow the 512-entry table at `table_pa` via HHDM for read.
346	fn table_ref(table_pa: u64) -> &'static [u64; PTES_PER_LEVEL] {
347	    // SAFETY: `table_pa` came from `alloc_frame`, so it is HHDM-mapped and
348	    // 4 KiB-aligned. Single-threaded boot — no concurrent writer.
349	    unsafe { &*(phys_to_hhdm(table_pa) as *const [u64; PTES_PER_LEVEL]) }
350	}
351	
352	/// Borrow the 512-entry table at `table_pa` via HHDM for mutation.
353	fn table_mut(table_pa: u64) -> &'static mut [u64; PTES_PER_LEVEL] {
354	    // SAFETY: `table_pa` came from `alloc_frame`, so it is HHDM-mapped and
355	    // 4 KiB-aligned. Single-threaded boot — no concurrent reader/writer.
356	    unsafe { &mut *(phys_to_hhdm(table_pa) as *mut [u64; PTES_PER_LEVEL]) }
357	}
358	
359	/// Return the PA of the child table at `parent[idx]`, or `None` if the slot
360	/// is empty or holds a non-table descriptor.
361	fn next_table(parent_pa: u64, idx: usize) -> Option<u64> {
362	    let desc = table_ref(parent_pa)[idx];
363	    if desc & PTE_VALID == 0 {
364	        return None;
365	    }
366	    // At L0/L1/L2, a table descriptor has PTE_TABLE=1; a valid entry with
367	    // PTE_TABLE=0 is a *block* descriptor (2 MiB / 1 GiB block) and must
368	    // NOT be followed as a sub-table. Slice 3.1a only ever writes table
369	    // descriptors via `ensure_next_table`, so this branch never fires
370	    // today — the check is future-proofing for any later slice that maps
371	    // a block (large-page support, identity ranges, etc.). (L3 page
372	    // descriptors also have PTE_TABLE=1, but we never call `next_table`
373	    // at L3.)
374	    if desc & PTE_TABLE == 0 {
375	        return None;
376	    }
377	    Some(desc & PA_MASK)
378	}
379	
380	/// Return the PA of the child table at `parent[idx]`, allocating and
381	/// linking it if absent.
382	fn ensure_next_table(parent_pa: u64, idx: usize) -> Result<u64, MapError> {
383	    let parent = table_mut(parent_pa);
384	    let desc = parent[idx];
385	    if desc & PTE_VALID != 0 {
386	        return Ok(desc & PA_MASK);
387	    }
388	    let child = alloc_frame().ok_or(MapError::OutOfMemory)?;
389	    parent[idx] = make_table_desc(child.addr());
390	    Ok(child.addr())
391	}
392	
393	/// Recursively free every intermediate table under `table_pa` at the given
394	/// `level` (0 = L0 root, 3 = L3 leaves). Page descriptors at L3 are left
395	/// alone (caller owns leaf frames); the table itself at L3 is freed by
396	/// the L2 recursion call. The L0 root is freed by [`AddrSpace::destroy`].
397	fn free_subtree(table_pa: u64, level: u32) {
398	    if level >= 3 {
399	        // L3 contains page descriptors, not table descriptors — nothing to
400	        // recurse into. The L3 frame itself was already linked at L2 and
401	        // will be freed by the L2 caller.
402	        return;
403	    }
404	    // Snapshot the entries into a local so the HHDM borrow of `table_pa`
405	    // ends before the recursive call (which takes fresh borrows of sibling
406	    // tables — overlapping `&` is fine for shared reads, but copying makes
407	    // the intent unambiguous).
408	    let entries: [u64; PTES_PER_LEVEL] = *table_ref(table_pa);
409	    for desc in entries.iter() {
410	        if *desc & PTE_VALID == 0 {
411	            continue;
412	        }
413	        let child_pa = *desc & PA_MASK;
414	        // Recurse to free grandchildren first, then free this child table.
415	        free_subtree(child_pa, level + 1);
416	        free_frame(Frame::from_addr(child_pa));
417	    }
418	}
