1	// SPDX-License-Identifier: BSD-3-Clause
2	// Copyright (c) 2025-2026 Kevin Barnard and minix.rs Contributors
3	//! `minix/callnr.h` — kernel-call numbers and the server request bands.
4	
5	use minixrs_kernel_shared::{callnr, grant};
6	
7	use crate::builder::CFile;
8	
9	/// Include guard for the generated header.
10	pub const GUARD: &str = "_MINIX_CALLNR_H";
11	
12	/// The 18 kernel calls, in numeric order.
13	fn kernel_calls() -> [(&'static str, i32); 18] {
14	    [
15	        ("SYS_GETINFO", callnr::SYS_GETINFO),
16	        ("SYS_PRIVCTL", callnr::SYS_PRIVCTL),
17	        ("SYS_FORK", callnr::SYS_FORK),
18	        ("SYS_EXEC", callnr::SYS_EXEC),
19	        ("SYS_EXIT", callnr::SYS_EXIT),
20	        ("SYS_COPY", callnr::SYS_COPY),
21	        ("SYS_SAFECOPY", callnr::SYS_SAFECOPY),
22	        ("SYS_IRQCTL", callnr::SYS_IRQCTL),
23	        ("SYS_VMCTL", callnr::SYS_VMCTL),
24	        ("SYS_SCHEDULE", callnr::SYS_SCHEDULE),
25	        ("SYS_SETALARM", callnr::SYS_SETALARM),
26	        ("SYS_TIMES", callnr::SYS_TIMES),
27	        ("SYS_DIAGCTL", callnr::SYS_DIAGCTL),
28	        ("SYS_SETGRANT", callnr::SYS_SETGRANT),
29	        ("SYS_SCHEDCTL", callnr::SYS_SCHEDCTL),
30	        ("SYS_KILL", callnr::SYS_KILL),
31	        ("SYS_GETKSIG", callnr::SYS_GETKSIG),
32	        ("SYS_ENDKSIG", callnr::SYS_ENDKSIG),
33	    ]
34	}
35	
36	/// The CPF grant flags, in numeric order.
37	fn cpf_flags() -> [(&'static str, u32); 8] {
38	    [
39	        ("CPF_READ", grant::CPF_READ),
40	        ("CPF_WRITE", grant::CPF_WRITE),
41	        ("CPF_TRY", grant::CPF_TRY),
42	        ("CPF_USED", grant::CPF_USED),
43	        ("CPF_DIRECT", grant::CPF_DIRECT),
44	        ("CPF_INDIRECT", grant::CPF_INDIRECT),
45	        ("CPF_MAGIC", grant::CPF_MAGIC),
46	        ("CPF_VALID", grant::CPF_VALID),
47	    ]
48	}
49	
50	/// An arbitrary `(idx, seq)` pair and its packed id, used by the header's
51	/// round-trip `_Static_assert`s. Both fields are non-zero and unequal, so a
52	/// macro that dropped or swapped one would fail the check.
53	const GRANT_PROBE_IDX: u32 = 1234;
54	const GRANT_PROBE_SEQ: u32 = 56;
55	const GRANT_PROBE_ID: i32 = grant::grant_id(GRANT_PROBE_IDX, GRANT_PROBE_SEQ);
56	
57	/// A server request band: base constant, its members, and the count constant
58	/// that bounds it (`None` for VM, which has no `NR_*` on the Rust side).
59	///
60	/// `members` is checked against `count` by
61	/// `every_band_member_list_matches_its_count`: a new request that bumps the Rust
62	/// `NR_*` without gaining a row here would otherwise render a larger count and
63	/// no macro for the request itself.
64	struct Band {
65	    title: &'static str,
66	    base_name: &'static str,
67	    base: i32,
68	    count: Option<(&'static str, usize)>,
69	    members: Vec<(&'static str, i32)>,
70	}
71	
72	fn bands() -> [Band; 5] {
73	    [
74	        Band {
75	            title: "PM requests",
76	            base_name: "PM_RQ_BASE",
77	            base: callnr::PM_RQ_BASE,
78	            count: Some(("NR_PM_MSGS", callnr::NR_PM_MSGS)),
79	            members: vec![
80	                ("PM_GETPID", callnr::PM_GETPID),
81	                ("PM_FORK", callnr::PM_FORK),
82	                ("PM_EXIT", callnr::PM_EXIT),
83	                ("PM_WAIT", callnr::PM_WAIT),
84	                ("PM_EXEC", callnr::PM_EXEC),
85	                ("PM_GRANT_TEST", callnr::PM_GRANT_TEST),
86	            ],
87	        },
88	        Band {
89	            title: "VM requests",
90	            base_name: "VM_RQ_BASE",
91	            base: callnr::VM_RQ_BASE,
92	            count: None,
93	            members: vec![
94	                ("VM_PAGEFAULT", callnr::VM_PAGEFAULT),
95	                ("VM_BRK", callnr::VM_BRK),
96	                ("VM_MMAP", callnr::VM_MMAP),
97	                ("VM_MUNMAP", callnr::VM_MUNMAP),
98	                ("VM_FORK", callnr::VM_FORK),
99	            ],
100	        },
101	        Band {
102	            title: "SEF control messages",
103	            base_name: "SEF_RQ_BASE",
104	            base: callnr::SEF_RQ_BASE,
105	            count: Some(("NR_SEF_MSGS", callnr::NR_SEF_MSGS)),
106	            members: vec![
107	                ("SEF_INIT", callnr::SEF_INIT),
108	                ("SEF_SIGNAL", callnr::SEF_SIGNAL),
109	            ],
110	        },
111	        Band {
112	            title: "DS requests",
113	            base_name: "DS_RQ_BASE",
114	            base: callnr::DS_RQ_BASE,
115	            count: Some(("NR_DS_REQUESTS", callnr::NR_DS_REQUESTS)),
116	            members: vec![
117	                ("DS_PUBLISH", callnr::DS_PUBLISH),
118	                ("DS_RETRIEVE", callnr::DS_RETRIEVE),
119	                ("DS_CHECK", callnr::DS_CHECK),
120	            ],
121	        },
122	        Band {
123	            title: "SCHED requests",
124	            base_name: "SCHED_RQ_BASE",
125	            base: callnr::SCHED_RQ_BASE,
126	            count: Some(("NR_SCHED_MSGS", callnr::NR_SCHED_MSGS)),
127	            members: vec![
128	                ("SCHEDULING_NO_QUANTUM", callnr::SCHEDULING_NO_QUANTUM),
129	                ("SCHEDULING_START", callnr::SCHEDULING_START),
130	                ("SCHEDULING_STOP", callnr::SCHEDULING_STOP),
131	                ("SCHEDULING_SET_NICE", callnr::SCHEDULING_SET_NICE),
132	            ],
133	        },
134	    ]
135	}
136	
137	/// Render `minix/callnr.h`.
138	pub fn render() -> String {
139	    let mut f = CFile::new(
140	        "Kernel-call numbers, server request bands, and their payload constants.",
141	        &["kernel-shared/src/callnr.rs"],
142	    );
143	    f.guard_open(GUARD);
144	
145	    f.blank();
146	    f.include(
147	        "minix/ipc.h",
148	        "NOTIFY_MESSAGE, for the band ordering checks",
149	    );
150	
151	    f.block_comment(&[
152	        "Deviation from MINIX 3: its <minix/callnr.h> holds POSIX syscall numbers",
153	        "and keeps server request numbers in <minix/com.h>. minix.rs has no POSIX",
154	        "call-number layer -- a libc wrapper builds a server request directly --",
155	        "so this header carries the kernel calls and the request bands together.",
156	        "",
157	        "Payload byte offsets are not emitted yet: on the Rust side they live in",
158	        "doc comments rather than constants. The first musl wrapper (slice 5.6) is",
159	        "the forcing function for promoting them to real constants.",
160	    ]);
161	
162	    f.section("kernel calls");
163	    f.define_hex("KERNEL_CALL", callnr::KERNEL_CALL.into());
164	    f.blank();
165	    for (name, value) in kernel_calls() {
166	        f.define_hex(name, value.into());
167	    }
168	    f.blank();
169	    // Name-matched with the Rust constant as of slice 5.1 (it was
170	    // `NR_KERN_CALLS_PHASE4` there, and carried a provenance comment here to
171	    // bridge the gap). Keep the two spellings identical past the 5.6 ABI
172	    // freeze — `nr_kern_calls_is_not_phase_suffixed` guards it.
173	    f.define_dec("NR_KERN_CALLS", callnr::NR_KERN_CALLS as i64);
174	    f.define_dec("NR_SYS_CALLS", callnr::NR_SYS_CALLS as i64);
175	
176	    f.section("kernel-call payload constants");
177	    f.define_dec("GET_WHOAMI", callnr::GET_WHOAMI.into());
178	    f.define_dec("SYS_GETINFO_NAME_LEN", callnr::SYS_GETINFO_NAME_LEN as i64);
179	    f.define_dec("EXEC_NAME_LEN", callnr::EXEC_NAME_LEN as i64);
180	    f.define_dec("PRIVCTL_SET_USER", callnr::PRIVCTL_SET_USER.into());
181	    f.define_dec("SCHEDCTL_FLAG_KERNEL", callnr::SCHEDCTL_FLAG_KERNEL.into());
182	
183	    f.section("SYS_DIAGCTL subcodes + inline-text payload");
184	    f.define_dec("DIAGCTL_CODE_DIAG", callnr::DIAGCTL_CODE_DIAG.into());
185	    f.define_dec(
186	        "DIAGCTL_CODE_STACKTRACE",
187	        callnr::DIAGCTL_CODE_STACKTRACE.into(),
188	    );
189	    f.define_dec(
190	        "DIAGCTL_CODE_REGISTER",
191	        callnr::DIAGCTL_CODE_REGISTER.into(),
192	    );
193	    f.define_dec(
194	        "DIAGCTL_CODE_UNREGISTER",
195	        callnr::DIAGCTL_CODE_UNREGISTER.into(),
196	    );
197	    f.define_dec("DIAG_TEXT_OFF", callnr::DIAG_TEXT_OFF as i64);
198	    f.define_dec("DIAG_TEXT_MAX", callnr::DIAG_TEXT_MAX as i64);
199	
200	    f.section("grants: SYS_SETGRANT / SYS_SAFECOPY");
201	    f.block_comment(&[
202	        "The grant ABI (slice 5.2). The grant-entry layout itself is deliberately",
203	        "not emitted yet: no C consumes it before the musl slice, and a dedicated",
204	        "<minix/safecopies.h> would need its own builder and CI syntax check. The",
205	        "flag values and the id packing are here because a C caller needs them to",
206	        "read a grant id out of a message payload.",
207	    ]);
208	    f.define_dec("SAFECOPY_FROM", callnr::SAFECOPY_FROM.into());
209	    f.define_dec("SAFECOPY_TO", callnr::SAFECOPY_TO.into());
210	    f.blank();
211	    for (name, value) in cpf_flags() {
212	        f.define_hex(name, value.into());
213	    }
214	    f.blank();
215	    f.define_dec("GRANT_SHIFT", grant::GRANT_SHIFT.into());
216	    f.define_hex("GRANT_MAX_IDX", grant::GRANT_MAX_IDX.into());
217	    f.define_hex("GRANT_MAX_SEQ", grant::GRANT_MAX_SEQ.into());
218	    f.define_dec("GRANT_INVALID", grant::GRANT_INVALID.into());
219	    f.blank();
220	    f.define_raw(
221	        "GRANT_ID(idx, seq)",
222	        "((int) ((((unsigned) (seq) & GRANT_MAX_SEQ) << GRANT_SHIFT) \\\n                                 | ((unsigned) (idx) & GRANT_MAX_IDX)))",
223	    );
224	    f.define_raw("GRANT_IDX(g)", "((unsigned) (g) & GRANT_MAX_IDX)");
225	    f.define_raw(
226	        "GRANT_SEQ(g)",
227	        "(((unsigned) (g) >> GRANT_SHIFT) & GRANT_MAX_SEQ)",
228	    );
229	    f.define_raw("GRANT_VALID(g)", "((g) >= 0)");
230	    f.blank();
231	    // Check the C packing against the Rust one rather than trusting that the
232	    // two expressions were transcribed the same way.
233	    f.static_assert(
234	        &format!(
235	            "GRANT_ID(GRANT_MAX_IDX, GRANT_MAX_SEQ) == {}",
236	            grant::grant_id(grant::GRANT_MAX_IDX, grant::GRANT_MAX_SEQ)
237	        ),
238	        "the C grant-id packing disagrees with the Rust one",
239	    );
240	    f.static_assert(
241	        &format!("GRANT_IDX({GRANT_PROBE_ID}) == {GRANT_PROBE_IDX}"),
242	        "GRANT_IDX does not invert GRANT_ID",
243	    );
244	    f.static_assert(
245	        &format!("GRANT_SEQ({GRANT_PROBE_ID}) == {GRANT_PROBE_SEQ}"),
246	        "GRANT_SEQ does not invert GRANT_ID",
247	    );
248	
249	    f.section("SYS_VMCTL subcalls");
250	    f.define_dec("VMCTL_PT_MAP", callnr::VMCTL_PT_MAP.into());
251	    f.define_dec("VMCTL_PT_UNMAP", callnr::VMCTL_PT_UNMAP.into());
252	    f.define_dec(
253	        "VMCTL_CLEAR_PAGEFAULT",
254	        callnr::VMCTL_CLEAR_PAGEFAULT.into(),
255	    );
256	    f.define_dec("VMCTL_GET_PAGEFAULT", callnr::VMCTL_GET_PAGEFAULT.into());
257	    f.define_dec("VMCTL_VMINHIBIT_SET", callnr::VMCTL_VMINHIBIT_SET.into());
258	    f.define_dec(
259	        "VMCTL_VMINHIBIT_CLEAR",
260	        callnr::VMCTL_VMINHIBIT_CLEAR.into(),
261	    );
262	    f.define_dec("NR_VMCTL_SUBCALLS", callnr::NR_VMCTL_SUBCALLS as i64);
263	    f.blank();
264	    f.define_dec("VMCTL_PROT_WRITE", callnr::VMCTL_PROT_WRITE.into());
265	    f.define_dec("VMCTL_PROT_EXEC", callnr::VMCTL_PROT_EXEC.into());
266	
267	    for band in bands() {
268	        f.section(band.title);
269	        f.define_hex(band.base_name, band.base.into());
270	        for (name, value) in &band.members {
271	            f.define_hex(name, (*value).into());
272	        }
273	        if let Some((count_name, count)) = band.count {
274	            f.define_dec(count_name, count as i64);
275	        }
276	    }
277	
278	    f.section("band ordering");
279	    f.block_comment(&[
280	        "Mirrors the `const _: () = assert!(..)` guards in callnr.rs: every band",
281	        "sits above the previous one and entirely below NOTIFY_MESSAGE, so no",
282	        "server request can ever be mistaken for a kernel NOTIFY.",
283	    ]);
284	    f.static_assert(
285	        "NR_SYS_CALLS >= NR_KERN_CALLS",
286	        "the privilege call mask is narrower than the kernel-call set",
287	    );
288	    f.static_assert(
289	        "PM_RQ_BASE > KERNEL_CALL + NR_KERN_CALLS - 1",
290	        "the PM band overlaps the kernel calls",
291	    );
292	    f.static_assert(
293	        "PM_RQ_BASE + NR_PM_MSGS - 1 < VM_RQ_BASE",
294	        "the PM band overlaps the VM band",
295	    );
296	    f.static_assert("SEF_RQ_BASE > VM_FORK", "the SEF band overlaps the VM band");
297	    f.static_assert(
298	        "DS_RQ_BASE > SEF_RQ_BASE + NR_SEF_MSGS - 1",
299	        "the DS band overlaps the SEF band",
300	    );
301	    f.static_assert(
302	        "SCHED_RQ_BASE > DS_RQ_BASE + NR_DS_REQUESTS - 1",
303	        "the SCHED band overlaps the DS band",
304	    );
305	    f.static_assert(
306	        "SCHED_RQ_BASE + NR_SCHED_MSGS - 1 < NOTIFY_MESSAGE",
307	        "a server request number collides with NOTIFY_MESSAGE",
308	    );
309	
310	    f.guard_close(GUARD);
311	    f.finish()
312	}
313	
314	#[cfg(test)]
315	mod tests {
316	    use super::*;
317	    use crate::builder;
318	
319	    #[test]
320	    fn kernel_calls_render_from_live_constants() {
321	        let text = render();
322	        for (name, value) in kernel_calls() {
323	            assert_eq!(
324	                builder::define_value(&text, name).as_deref(),
325	                Some(format!("0x{value:X}").as_str()),
326	                "{name} did not render from its Rust constant"
327	            );
328	        }
329	    }
330	
331	    #[test]
332	    fn the_kernel_call_list_is_complete_and_contiguous() {
333	        let calls = kernel_calls();
334	        assert_eq!(calls.len(), callnr::NR_KERN_CALLS);
335	        for (i, (name, value)) in calls.into_iter().enumerate() {
336	            assert_eq!(
337	                value,
338	                callnr::KERNEL_CALL + i as i32,
339	                "{name} is out of order"
340	            );
341	        }
342	    }
343	
344	    #[test]
345	    fn every_band_base_member_and_count_appears() {
346	        let text = render();
347	        for band in bands() {
348	            assert_eq!(
349	                builder::define_value(&text, band.base_name).as_deref(),
350	                Some(format!("0x{:X}", band.base).as_str())
351	            );
352	            for (name, value) in &band.members {
353	                assert_eq!(
354	                    builder::define_value(&text, name).as_deref(),
355	                    Some(format!("0x{value:X}").as_str()),
356	                    "{name} missing from the {} band",
357	                    band.title
358	                );
359	            }
360	            if let Some((count_name, count)) = band.count {
361	                assert_eq!(
362	                    builder::define_value(&text, count_name).as_deref(),
363	                    Some(count.to_string().as_str())
364	                );
365	            }
366	        }
367	    }
368	
369	    /// The completeness half of the band lock: `every_band_base_member_and_count_appears`
370	    /// only proves that whatever is listed renders, so on its own a new request
371	    /// that bumped `NR_PM_MSGS` would grow the C count and the ordering asserts
372	    /// while silently omitting its own macro. Each band's members must therefore
373	    /// be exactly `count` entries, contiguous from `base`.
374	    #[test]
375	    fn every_band_member_list_matches_its_count() {
376	        for band in bands() {
377	            if let Some((count_name, count)) = band.count {
378	                assert_eq!(
379	                    band.members.len(),
380	                    count,
381	                    "the {} band lists {} members but {count_name} is {count}",
382	                    band.title,
383	                    band.members.len()
384	                );
385	            }
386	            for (i, (name, value)) in band.members.iter().enumerate() {
387	                assert_eq!(
388	                    *value,
389	                    band.base + i as i32,
390	                    "{name} is out of order in the {} band",
391	                    band.title
392	                );
393	            }
394	        }
395	    }
396	
397	    /// VM is the one band with no `NR_*` count on the Rust side, so its guard
398	    /// names the last member instead. Pin both the guard text and the member the
399	    /// guard names, so a future `NR_VM_MSGS` — or a `VM_RQ_BASE + 5` request —
400	    /// is a deliberate change here rather than a silent gap.
401	    #[test]
402	    fn the_vm_band_has_no_count_constant() {
403	        let vm = bands()
404	            .into_iter()
405	            .find(|b| b.base_name == "VM_RQ_BASE")
406	            .unwrap();
407	        assert!(vm.count.is_none());
408	        assert_eq!(
409	            vm.members.last().map(|(name, value)| (*name, *value)),
410	            Some(("VM_FORK", callnr::VM_FORK)),
411	            "the SEF ordering assert names the VM band's last member"
412	        );
413	        assert!(render().contains("SEF_RQ_BASE > VM_FORK"));
414	    }
415	
416	    #[test]
417	    fn grant_constants_render_from_live_constants() {
418	        let text = render();
419	        for (name, value) in cpf_flags() {
420	            assert_eq!(
421	                builder::define_value(&text, name).as_deref(),
422	                Some(format!("0x{value:X}").as_str()),
423	                "{name} did not render from its Rust constant"
424	            );
425	        }
426	        assert_eq!(
427	            builder::define_value(&text, "GRANT_SHIFT").as_deref(),
428	            Some(grant::GRANT_SHIFT.to_string().as_str())
429	        );
430	        assert_eq!(
431	            builder::define_value(&text, "GRANT_MAX_IDX").as_deref(),
432	            Some(format!("0x{:X}", grant::GRANT_MAX_IDX).as_str())
433	        );
434	        assert_eq!(
435	            builder::define_value(&text, "GRANT_MAX_SEQ").as_deref(),
436	            Some(format!("0x{:X}", grant::GRANT_MAX_SEQ).as_str())
437	        );
438	        // Negative values render parenthesized, so a `-1` cannot be pasted into
439	        // a larger expression and change its meaning.
440	        assert_eq!(
441	            builder::define_value(&text, "GRANT_INVALID").as_deref(),
442	            Some("(-1)")
443	        );
444	    }
445	
446	    /// The C grant-id macros are a second implementation of the Rust packing, so
447	    /// the header carries `_Static_assert`s tying them together. Check the
448	    /// asserted values come from the Rust helpers rather than being transcribed.
449	    #[test]
450	    fn the_grant_id_macro_asserts_use_rust_computed_values() {
451	        let text = render();
452	        let max = grant::grant_id(grant::GRANT_MAX_IDX, grant::GRANT_MAX_SEQ);
453	        assert!(text.contains(&format!("GRANT_ID(GRANT_MAX_IDX, GRANT_MAX_SEQ) == {max}")));
454	        assert!(text.contains(&format!("GRANT_IDX({GRANT_PROBE_ID}) == {GRANT_PROBE_IDX}")));
455	        assert!(text.contains(&format!("GRANT_SEQ({GRANT_PROBE_ID}) == {GRANT_PROBE_SEQ}")));
456	        // The probe must actually exercise both fields.
457	        assert_eq!(grant::grant_idx(GRANT_PROBE_ID), GRANT_PROBE_IDX);
458	        assert_eq!(grant::grant_seq(GRANT_PROBE_ID), GRANT_PROBE_SEQ);
459	        assert_ne!(GRANT_PROBE_IDX, GRANT_PROBE_SEQ);
460	    }
461	
462	    #[test]
463	    fn safecopy_selectors_render_from_live_constants() {
464	        let text = render();
465	        assert_eq!(
466	            builder::define_value(&text, "SAFECOPY_FROM").as_deref(),
467	            Some(callnr::SAFECOPY_FROM.to_string().as_str())
468	        );
469	        assert_eq!(
470	            builder::define_value(&text, "SAFECOPY_TO").as_deref(),
471	            Some(callnr::SAFECOPY_TO.to_string().as_str())
472	        );
473	    }
474	
475	    /// `GrantEntry` is deliberately not emitted as a C struct until a C caller
476	    /// needs it (slice 5.6). Nothing may quietly add one here — that belongs in
477	    /// its own `<minix/safecopies.h>` with its own CI syntax check.
478	    #[test]
479	    fn no_grant_struct_is_emitted_yet() {
480	        let text = render();
481	        assert!(!text.contains("cp_grant_entry"));
482	        assert!(!text.contains("struct "));
483	    }
484	
485	    /// The C name and the Rust name must stay identical. The Rust constant was
486	    /// `NR_KERN_CALLS_PHASE4` until slice 5.1, which renamed it to match this
487	    /// header rather than let a phase-scoped name outlive Phase 4 and cross the
488	    /// slice-5.6 ABI freeze. Nothing may reintroduce a phase suffix on either
489	    /// side.
490	    #[test]
491	    fn nr_kern_calls_is_not_phase_suffixed() {
492	        let text = render();
493	        assert_eq!(
494	            builder::define_value(&text, "NR_KERN_CALLS").as_deref(),
495	            Some(callnr::NR_KERN_CALLS.to_string().as_str())
496	        );
497	        assert!(
498	            !text.contains("PHASE"),
499	            "the ABI header must carry no phase-scoped names"
500	        );
501	    }
502	}
