213	/// Free every leaf frame in the dead proc's page-table tree, invalidate its
214	/// TLB entries, free the tree itself, and recycle the ASID. Returns the leaf
215	/// count (the trace's frame-leak canary). No-op for procs that never ran at
216	/// EL0 (`ttbr0_pa == 0`: kernel tasks, never-loaded boot servers).
217	///
218	/// Shared with `do_exec`, which reuses it to reclaim the *old* image's address
219	/// space after swapping in the new one — the same "not the active TTBR0"
220	/// invariant holds there (exec's target is never the running caller).
221	pub(super) fn teardown_addrspace(ttbr0_pa: u64, dead_asid: u8) -> u64 {
222	    if ttbr0_pa == 0 {
223	        return 0;
224	    }
225	    let mut freed: u64 = 0;
226	    // The leaf walk must precede `destroy` (which frees the tables the walk
227	    // reads). Leaf frames are exclusively the dead proc's: fork copies pages
228	    // rather than sharing them, and `VMCTL_PT_MAP` allocates fresh frames.
229	    let _ = walk_leaves(ttbr0_pa, &mut |_va, pa, _prot| {
230	        free_frame(Frame::from_addr(pa));
231	        freed += 1;
232	        Ok(())
233	    });
234	    // SAFETY: single-threaded EL1; the dead proc's AS is never the active
235	    // TTBR0 (self-exit is rejected), so invalidating its ASID cannot yank
236	    // translations out from under the running caller.
237	    unsafe { mmu::flush_tlb_asid(dead_asid) };
238	    AddrSpace { ttbr0_pa }.destroy();
