        "CDEV_LEN_OFF",
        "CDEV_OFFSET_OFF",
        "CDEV_MAX_IO",
        "CDEV_MINOR_CONSOLE",
    ] {
        assert!(
            builder::define_value(&text, name).is_none(),
            "{name} must wait for the musl slice"
        );
    }
}

