    fn chunk_len_caps_at_the_payload_budget() {
        assert_eq!(chunk_len(DIAG_TEXT_MAX), DIAG_TEXT_MAX);
        assert_eq!(chunk_len(DIAG_TEXT_MAX + 1), DIAG_TEXT_MAX);
        assert_eq!(chunk_len(10 * DIAG_TEXT_MAX), DIAG_TEXT_MAX);
    }

