    fn chunking_covers_every_byte_exactly_once() {
        // Mirror `diag_print`'s loop without the IPC trap: the chunk lengths
        // must tile the input with no gap, overlap, or zero-length step.
        for total in [
            0,
            1,
            DIAG_TEXT_MAX - 1,
            DIAG_TEXT_MAX,
            DIAG_TEXT_MAX + 1,
            500,
