380	/// PM holds `SYS_COPY` and `SYS_SAFECOPY`; its clients — init, and every forked
381	/// child on the shared USER privilege — hold neither. A caller-supplied granter
382	/// endpoint would therefore let any of them aim a privileged cross-address-space
383	/// copy at a third party *through PM*, and read back a checksum of the result: a
384	/// textbook confused deputy. The granter is the kernel-stamped `m_source`
385	/// instead (the anti-spoof property DS relies on for `DS_PUBLISH`), so a client
386	/// can only ever name its own address space. The request is additionally served
387	/// only when that source is VFS, since nothing else has business driving a
388	/// demo-only request number.
389	#[cfg_attr(test, allow(dead_code))]
390	fn handle_grant_test(
391	    system: Endpoint,
392	    own_e: Endpoint,
393	    grants: &mut GrantPool<GRANT_SLOTS>,
394	    msg: &Message,
395	) {
396	    // The granter is whoever the kernel says sent this, never a payload field.
397	    let granter = msg.m_source;
398	    if granter != boot_endpoint(VFS_PROC_NR) {
399	        return;
400	    }
401	    let gid = rd_i32(msg, 0);
402	    let rw_gid = rd_i32(msg, 8);
403	    let raw_addr = rd_u64(msg, 16);
404	    // Clamp to PM's staging buffer rather than trusting the sender's length.
405	    let len = match usize::try_from(rd_i32(msg, 4)) {
406	        Ok(n) if n <= GRANT_TEST_MAX => n,
407	        _ => GRANT_TEST_MAX,
408	    };
409	
410	    // 1. Through the grant.
411	    let mut buf = [0u8; GRANT_TEST_MAX];
412	    let rc = sys_safecopy(
413	        system,
414	        SAFECOPY_FROM,
415	        granter,
416	        gid,
417	        0,
418	        buf_addr(&mut buf),
419	        len as u64,
420	    );
421	    let grant_sum = checksum(&buf[..len]);
422	    if rc == OK {
423	        diag_line(format_args!("grant.test ok sum={grant_sum} len={len}"));
424	    } else {
425	        diag_line(format_args!("grant.test FAIL rc={rc}"));
426	        return;
427	    }
428	
429	    // 2. The same bytes with no grant, straight out of VFS's address space.
430	    let mut raw = [0u8; GRANT_TEST_MAX];
431	    let rc = sys_copy(
432	        system,
433	        granter,
434	        raw_addr,
435	        SELF,
436	        buf_addr(&mut raw),
437	        len as u64,
438	    );
439	    if rc == OK {
440	        let same = u8::from(checksum(&raw[..len]) == grant_sum);
441	        diag_line(format_args!("copy ok match={same}"));
442	    } else {
443	        diag_line(format_args!("copy FAIL rc={rc}"));
444	    }
445	
446	    // 3. Magic: PM grants itself access to init's memory, then reads it.
447	    let mut probe = [0u8; MAGIC_PROBE_LEN];
448	    match grants.grant_magic(
449	        own_e,
450	        boot_endpoint(INIT_PROC_NR),
451	        MAGIC_PROBE_VA,
452	        MAGIC_PROBE_LEN as u64,
453	        CPF_READ,
454	    ) {
455	        Ok(mgid) => {
456	            let rc = sys_safecopy(
457	                system,
458	                SAFECOPY_FROM,
459	                own_e,
460	                mgid,
461	                0,
462	                buf_addr(&mut probe),
463	                MAGIC_PROBE_LEN as u64,
464	            );
465	            if rc == OK {
466	                diag_line(format_args!("magic ok len={MAGIC_PROBE_LEN}"));
467	            } else {
468	                diag_line(format_args!("magic FAIL rc={rc}"));
469	            }
470	            let _ = grants.revoke(mgid);
471	        }
472	        Err(e) => diag_line(format_args!("magic FAIL grant={e}")),
473	    }
474	
475	    // 4. The copies that must be refused.
476	    grant_denials(system, own_e, grants, granter, gid, rw_gid, len as u64);
477	}
478	
479	/// Probe the checks that no *successful* copy exercises.
480	///
481	/// Slice 5.1's lesson, applied to grants: a validator no marker exercises is a
482	/// validator that can regress silently. Each case is constructed so that every
483	/// check but the one it targets passes — remove that check from the kernel and
484	/// the copy succeeds, flipping this line from `ok` to `FAIL <name>`.
485	///
486	/// The `rodata` case is the important one and the reason VFS issues a second,
487	/// deliberately-lying grant: a granter may claim `CPF_WRITE` over memory that is
488	/// not writable, and the kernel copies through its own HHDM alias where the
489	/// MMU's EL0 permission bits do not apply. `EFAULT` (not `EPERM`) is the
490	/// expected answer there — the *grant* is in order; the destination page is not.
491	/// `unmapped` is the same distinction on the read side: a well-formed grant over
492	/// a page nothing backs, refused by the walk rather than by any grant check.
493	///
494	/// Two arms are not probed. `CPF_INDIRECT` cannot be, because [`GrantPool`] has
495	/// no API to mint an indirect grant (D4 defers them). The magic path's
