1	// SPDX-License-Identifier: BSD-3-Clause
2	// Copyright (c) 2025-2026 Kevin Barnard and minix.rs Contributors
3	//! Native-endian scalar accessors for a [`Message`] payload.
4	//!
5	//! Every server and driver marshals its requests by hand — there is no typed
6	//! message-union layer in minix.rs (MINIX 3's `m1`/`m2`/… structs), because a
7	//! payload offset is documented per request in `kernel-shared::callnr` and
8	//! reading it by offset keeps the ABI in one place. What that leaves is these
9	//! four one-line accessors, which had been copied into PM, VFS, VM, DS, and
10	//! SCHED. Slice 5.3 lifted them here rather than copy them a sixth time into
11	//! `drivers/tty`.
12	//!
13	//! Native-endian on purpose: both ends of every message are the same machine, and
14	//! the generated C headers describe the payload as raw bytes at an offset. There
15	//! is no wire format to agree on.
16	//!
17	//! Out-of-range offsets and short slices are handled by returning `0` / writing
18	//! nothing rather than panicking. A server has no business dying on a malformed
19	//! request from a client it does not trust, and `0` is a value every request's
20	//! own validation already has to reject (endpoint `NONE` is `0`, grant id `0` has
21	//! sequence 0, length `0` is a no-op).
22	
23	use minixrs_kernel_shared::Message;
24	
25	/// Read a native-endian `i32` from payload `off..off+4`. Returns `0` if the range
26	/// does not fit the payload.
27	pub fn rd_i32(m: &Message, off: usize) -> i32 {
28	    match m.payload.get(off..off + 4) {
29	        Some(b) => i32::from_ne_bytes(b.try_into().unwrap_or([0; 4])),
30	        None => 0,
31	    }
32	}
33	
34	/// Write a native-endian `i32` into payload `off..off+4`. No-op if the range does
35	/// not fit the payload.
36	pub fn wr_i32(m: &mut Message, off: usize, v: i32) {
37	    if let Some(b) = m.payload.get_mut(off..off + 4) {
38	        b.copy_from_slice(&v.to_ne_bytes());
39	    }
40	}
41	
42	/// Read a native-endian `u64` from payload `off..off+8`. Returns `0` if the range
43	/// does not fit the payload.
44	pub fn rd_u64(m: &Message, off: usize) -> u64 {
45	    match m.payload.get(off..off + 8) {
46	        Some(b) => u64::from_ne_bytes(b.try_into().unwrap_or([0; 8])),
47	        None => 0,
48	    }
49	}
50	
51	/// Write a native-endian `u64` into payload `off..off+8`. No-op if the range does
52	/// not fit the payload.
53	pub fn wr_u64(m: &mut Message, off: usize, v: u64) {
54	    if let Some(b) = m.payload.get_mut(off..off + 8) {
55	        b.copy_from_slice(&v.to_ne_bytes());
56	    }
57	}
