59	/// The address of a local staging buffer, in the form the kernel's copy calls
60	/// want it (`SYS_COPY` / `SYS_SAFECOPY` take a plain `u64` VA).
61	///
62	/// `&mut` rather than `&`: the kernel writes through *its own* mapping of this
63	/// frame (the HHDM alias), not through this pointer, so the borrow checker cannot
64	/// see the write. Requiring an exclusive borrow is what stops a caller handing
65	/// over a buffer it is simultaneously reading. The SENDREC's inline asm is a full
66	/// memory clobber, so the compiler cannot cache the buffer's contents across the
67	/// call either.
68	pub fn buf_addr(b: &mut [u8]) -> u64 {
69	    b.as_mut_ptr() as usize as u64
70	}
