1	// SPDX-License-Identifier: BSD-3-Clause
2	// Copyright (c) 2025-2026 Kevin Barnard and minix.rs Contributors
3	//! minix.rs VFS (virtual file system) server — skeletal boot (slice 4.2), plus
4	//! the slice-5.2 grant demo.
5	//!
6	//! Slice 4.2 stood VFS up as a real boot server: it boots through the SEF
7	//! framework and publishes its endpoint to DS, proving the multi-server boot
8	//! path and the DS registry end to end. It does *no* file operations yet — the
9	//! PM↔VFS fork/exec work protocol needs file descriptors and is Phase 5 — so the
10	//! receive loop simply drops any application traffic that arrives.
11	//!
12	//! Slice 5.2 gives VFS the granting half of the first real cross-address-space
13	//! copy: it direct-grants a checksummed read-only buffer to PM and hands PM the
14	//! grant id in a `PM_GRANT_TEST` message. See [`grant_test`].
15	//!
16	//! Built as a freestanding aarch64 ELF (see `servers/vfs/user.ld`), packed into
17	//! the kernel's boot-image archive by `kernel/build.rs`, and loaded into its own
18	//! per-process AddrSpace at boot by `arch::aarch64::userland::load_boot_server`.
19	
20	// Freestanding for the real (bare-metal) build, but a normal host binary under
21	// `cargo test` (no host tests yet — the SEF/IPC glue is QEMU-verified). The
22	// `_start` shim and panic handler are gated to `not(test)`.
23	#![cfg_attr(not(test), no_std)]
24	#![cfg_attr(not(test), no_main)]
25	
26	use minixrs_ipc::ipc_send;
27	use minixrs_kernel_shared::Message;
28	use minixrs_kernel_shared::callnr::{PM_GRANT_TEST, SYS_GETINFO_NAME_LEN};
29	use minixrs_kernel_shared::com::{PM_PROC_NR, boot_endpoint};
30	use minixrs_kernel_shared::endpoint::Endpoint;
31	use minixrs_kernel_shared::grant::{CPF_READ, CPF_WRITE};
32	use minixrs_server_rt::{GrantPool, SefConfig, sef_publish_to_ds, sef_startup};
33	
34	/// Bytes VFS grants PM in the slice-5.2 demo.
35	const GRANT_TEST_LEN: usize = 64;
36	
37	/// Number of simultaneously outstanding grants VFS can hold. VFS's stack is one
38	/// page, and the pool costs `N * 32` bytes; 8 is ample for the demo.
39	const GRANT_SLOTS: usize = 8;
40	
41	/// The granted buffer. A `static` (not `static mut`) so it lands in `.rodata`,
42	/// which the ELF loader maps read-only — exactly right for a `CPF_READ` grant,
43	/// and it means the kernel's `Prot::writable` check would reject any attempt to
44	/// safecopy *into* it.
45	static GRANT_TEST_BUF: [u8; GRANT_TEST_LEN] = grant_test_pattern();
46	
47	/// A deterministic, non-trivial byte pattern. Deterministic so PM's checksum is
48	/// a fixed value across runs; non-trivial (not `i`, not a constant) so a copy
49	/// that lost or duplicated a chunk still changes the sum.
50	const fn grant_test_pattern() -> [u8; GRANT_TEST_LEN] {
51	    let mut b = [0u8; GRANT_TEST_LEN];
52	    let mut i = 0;
53	    while i < GRANT_TEST_LEN {
54	        b[i] = (i as u8).wrapping_mul(37).wrapping_add(11);
55	        i += 1;
56	    }
57	    b
58	}
59	
60	/// ELF entry point. The kernel primes `SP_EL0` before `eret`, so `_start` can
61	/// dive straight into Rust without setting up a stack itself.
62	#[cfg(not(test))]
63	#[unsafe(no_mangle)]
64	#[cfg_attr(target_os = "none", unsafe(link_section = ".text._start"))]
65	pub extern "C" fn _start() -> ! {
66	    main()
67	}
68	
69	#[cfg_attr(test, allow(dead_code))]
70	fn main() -> ! {
71	    // `sef_startup` learns VFS's endpoint/name and runs `vfs_init`, which
72	    // publishes VFS's endpoint to DS. The publish SENDREC blocks until DS is in
73	    // its receive loop — safe at boot (DS's init does no IPC). No signal
74	    // handling. On startup failure there is no recovery and nothing to print.
75	    let sef = sef_startup(SefConfig {
76	        init_fresh: Some(vfs_init),
77	        signal_handler: None,
78	    })
79	    .unwrap_or_else(|_| {
80	        loop {
81	            core::hint::spin_loop()
82	        }
83	    });
84	
85	    // The grant pool is a `main`-frame value that outlives the receive loop
86	    // below — it cannot live in `init_fresh`, whose frame is gone by the time a
87	    // grantee safecopies. (`server-rt` keeps the table as a value rather than a
88	    // static precisely so it can be owned like this.)
89	    let mut grants: GrantPool<GRANT_SLOTS> = GrantPool::new();
90	    grant_test(&mut grants);
91	
92	    let mut msg = Message {
93	        m_source: 0,
94	        m_type: 0,
95	        payload: [0u8; 96],
96	    };
97	    loop {
98	        // No file ops yet (Phase 5): receive and drop application traffic. The
99	        // SEF framework still services control traffic (pings/signals/re-init)
100	        // inside `receive`; only the application messages it hands back are
101	        // discarded here.
102	        let _ = sef.receive(&mut msg);
103	    }
104	}
105	
106	/// Slice 5.2 demo: direct-grant [`GRANT_TEST_BUF`] to PM and tell PM about it.
107	///
108	/// The grant id travels **in-band**, in the `PM_GRANT_TEST` payload, which is
109	/// how grant ids really travel (slice 5.3's `CDEV_WRITE {minor, granter,
110	/// grant_id, len}` has the same shape). DS could not carry one: `DS_PUBLISH`
111	/// registers the kernel-stamped `m_source` and ignores the payload, which is
112	/// exactly its anti-spoof property.
113	///
114	/// `ipc_send` blocks until PM's receive loop picks the message up, so the demo
115	/// is self-synchronizing — no assumption is made about the two servers' SEF init
116	/// ordering. There is no cycle: VFS's own init only SENDRECs DS, and PM never
117	/// sends to VFS.
118	///
119	/// The buffer's raw address rides along too, so PM can read the same bytes a
120	/// second time with the ungranted `SYS_COPY` and compare.
121	///
122	/// A **second** grant over the same read-only buffer goes out claiming
123	/// `CPF_WRITE` — a granter lying about what its own memory permits. Nothing
124	/// stops a granter writing that entry, and the kernel copies through its own
125	/// HHDM alias where EL0 permission bits do not apply, so the only thing between
126	/// that lie and a corrupted `.rodata` page is the copy engine's explicit
127	/// `Prot::writable` check. PM probes it (`grant_denials`); this is the grant-path
128	/// analogue of slice 5.1's fourth bad-pointer probe.
129	///
130	/// Best-effort throughout: a failure here must not stop VFS from serving.
131	#[cfg_attr(test, allow(dead_code))]
132	fn grant_test(grants: &mut GrantPool<GRANT_SLOTS>) {
133	    let pm = boot_endpoint(PM_PROC_NR);
134	    let addr = (&raw const GRANT_TEST_BUF) as usize as u64;
135	    let len = GRANT_TEST_LEN as u64;
136	    let (Ok(gid), Ok(rw_gid)) = (
137	        grants.grant_direct(pm, addr, len, CPF_READ),
138	        grants.grant_direct(pm, addr, len, CPF_READ | CPF_WRITE),
139	    ) else {
140	        return;
141	    };
142	
143	    // No granter field: PM reads that off the kernel-stamped `m_source`, so
144	    // nothing in this payload can redirect PM's privileged copies at a third
145	    // party.
146	    let mut msg = Message {
147	        m_source: 0,
148	        m_type: PM_GRANT_TEST,
149	        payload: [0u8; 96],
150	    };
151	    msg.payload[0..4].copy_from_slice(&gid.to_ne_bytes());
152	    msg.payload[4..8].copy_from_slice(&(GRANT_TEST_LEN as i32).to_ne_bytes());
153	    msg.payload[8..12].copy_from_slice(&rw_gid.to_ne_bytes());
154	    msg.payload[16..24].copy_from_slice(&addr.to_ne_bytes());
155	    let _ = ipc_send(pm, &mut msg);
156	}
157	
158	/// SEF fresh-init callback: publish VFS's endpoint to DS under its name. DS
159	/// registers the caller's kernel-stamped endpoint, so `_endpoint` from
160	/// `GET_WHOAMI` is not sent.
161	#[cfg_attr(test, allow(dead_code))]
162	fn vfs_init(_endpoint: Endpoint, name: &[u8; SYS_GETINFO_NAME_LEN]) -> i32 {
163	    sef_publish_to_ds(name)
164	}
165	
166	// The freestanding panic handler; under `cargo test` std supplies its own.
167	#[cfg(not(test))]
168	#[panic_handler]
169	fn panic(_: &core::panic::PanicInfo) -> ! {
170	    loop {
171	        core::hint::spin_loop()
172	    }
173	}
